fn identity_cases(seed: u64, mut check: impl FnMut(&[Statement], &Args, bool) -> bool) {
    let mut r = Rng(seed);
    let mut hits = 0;
    for _ in 0..N {
        let (_, sts) = identity_policy(&mut r);
        let q = request(&mut r);
        let a = kargs(&q);
        let e = env(&q.conds);
        let allowed = policy_is_allowed(&sts, &a, &e);
        if check(&sts, &a, allowed) {
            hits += 1;
        }
    }
    assert!(hits >= MIN_HITS, "premises held {hits} times");
}

#[test]
fn identity_policies_agree() {
    let mut r = Rng(0x1D3A_77F0_0C0F_FEE1);
    let mut allowed = 0;
    let n = 400_000;
    for i in 0..n {
        let (p, sts) = identity_policy(&mut r);
        let q = request(&mut r);
        let want = upstream_identity(&p, &q);
        let got = policy_is_allowed(&sts, &kargs(&q), &env(&q.conds));
        assert_eq!(got, want, "case {i}: {}\n{:?} {} {}/{} {:?} {:?}", serde_json::to_string(&p).unwrap(),
            q.action, q.account, q.bucket, q.object, q.conds, q.claims);
        allowed += want as usize;
    }
    assert!(allowed > n / 20 && allowed < n - n / 20, "{allowed}");
}
